ServerEvents.commandRegistry(event => {
  const { commands: Commands } = event
  event.register(Commands.literal('skyworks_selftest').requires(s => s.hasPermission(2)).executes(ctx => {
    const server = ctx.source.server
    const RL = Java.loadClass('net.minecraft.resources.ResourceLocation')
    const Reg = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries')
    const rm = server.getRecipeManager()
    let bad = []
    for (let id of SKYWORKS_SELFTEST.recipes) if (!rm.byKey(RL.parse(id)).isPresent()) bad.push('recipe ' + id)
    for (let id of SKYWORKS_SELFTEST.items) if (!Reg.ITEM.containsKey(RL.parse(id))) bad.push('item ' + id)
    for (let id of SKYWORKS_SELFTEST.fluids) if (!Reg.FLUID.containsKey(RL.parse(id))) bad.push('fluid ' + id)
    const pd = server.persistentData
    const island = pd.getBoolean('skyworks_start_island') ? ('start island at ' + pd.getInt('skyworks_start_x') + ',' + pd.getInt('skyworks_start_y') + ',' + pd.getInt('skyworks_start_z')) : 'start island NOT placed'
    const total = SKYWORKS_SELFTEST.recipes.length + SKYWORKS_SELFTEST.items.length + SKYWORKS_SELFTEST.fluids.length
    const msg = bad.length === 0 ? `SKYWORKS SELFTEST PASS (${total} checks; ${island})` : `SKYWORKS SELFTEST FAIL (${bad.length}/${total}): ${bad.join(', ')} (${island})`
    ctx.source.sendSystemMessage(Text.of(msg))
    console.info('[Skyworks] ' + msg)
    return bad.length === 0 ? 1 : 0
  }))
})
